#include "oa_native_filter.h"
#include "native_filter_shader.h"
#include <string.h>
extern GLuint oa_post_program(const char *,const char *);
static const char *vs="#version 300 es\nvoid main(){vec2 p=vec2(float((gl_VertexID<<1)&2),float(gl_VertexID&2));gl_Position=vec4(p*2.-1.,0.,1.);}";
void oa_native_filter_close(oa_native_filter *p){if(p->tex)glDeleteTextures(1,&p->tex);if(p->fbo)glDeleteFramebuffers(1,&p->fbo);if(p->program)glDeleteProgram(p->program);if(p->vao)glDeleteVertexArrays(1,&p->vao);if(p->sampler)glDeleteSamplers(1,&p->sampler);memset(p,0,sizeof(*p));}
int oa_native_filter_open(oa_native_filter *p,int w,int h){memset(p,0,sizeof(*p));if(w<=0||h<=0)return 0;p->w=w;p->h=h;p->program=oa_post_program(vs,oa_native_filter_fs);if(!p->program)goto fail;glGenTextures(1,&p->tex);glBindTexture(GL_TEXTURE_2D,p->tex);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA8,w,h,0,GL_RGBA,GL_UNSIGNED_BYTE,0);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_REPEAT);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_REPEAT);glGenFramebuffers(1,&p->fbo);glBindFramebuffer(GL_FRAMEBUFFER,p->fbo);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,p->tex,0);if(glCheckFramebufferStatus(GL_FRAMEBUFFER)!=GL_FRAMEBUFFER_COMPLETE)goto fail;glGenVertexArrays(1,&p->vao);glGenSamplers(1,&p->sampler);glSamplerParameteri(p->sampler,GL_TEXTURE_MIN_FILTER,GL_LINEAR);glSamplerParameteri(p->sampler,GL_TEXTURE_MAG_FILTER,GL_LINEAR);glSamplerParameteri(p->sampler,GL_TEXTURE_WRAP_S,GL_REPEAT);glSamplerParameteri(p->sampler,GL_TEXTURE_WRAP_T,GL_REPEAT);glBindFramebuffer(GL_FRAMEBUFFER,0);p->ready=glGetError()==GL_NO_ERROR;if(p->ready)return 1;fail:oa_native_filter_close(p);glBindFramebuffer(GL_FRAMEBUFFER,0);return 0;}
void oa_native_filter_begin(oa_native_filter *p){if(!p||!p->ready)return;glBindFramebuffer(GL_FRAMEBUFFER,p->fbo);glViewport(0,0,p->w,p->h);glDisable(GL_DITHER);}
void oa_native_filter_draw(oa_native_filter *p,GLuint source,GLuint target,int w,int h){float c[8]={0};if(!p||!p->ready||w<=0||h<=0)return;c[0]=2.f/p->w;c[1]=2.f/p->h;c[2]=.5f/p->w;c[3]=.5f/p->h;c[4]=1.f/p->w;c[5]=1.f/p->h;glBindFramebuffer(GL_FRAMEBUFFER,target);glViewport(0,0,w,h);glDisable(GL_DEPTH_TEST);glDepthMask(GL_FALSE);glDisable(GL_BLEND);glDisable(GL_CULL_FACE);glDisable(GL_SCISSOR_TEST);glDisable(GL_DITHER);glColorMask(GL_TRUE,GL_TRUE,GL_TRUE,GL_TRUE);glUseProgram(p->program);glUniform4fv(glGetUniformLocation(p->program,"c[0]"),2,c);glUniform2f(glGetUniformLocation(p->program,"nativeExtent"),(float)w,(float)h);glActiveTexture(GL_TEXTURE0);glBindTexture(GL_TEXTURE_2D,source?source:p->tex);glBindSampler(0,p->sampler);glUniform1i(glGetUniformLocation(p->program,"src"),0);glBindVertexArray(p->vao);glDrawArrays(GL_TRIANGLES,0,3);glBindSampler(0,0);}
